-- 0038: تحميل النص الرسمي للقانون 38/2026 (الجريدة الرسمية العدد 3 تاريخ 15/1/2026) وتفصيل قواعده. تبقى كلها pending_review حتى يؤكدها محامٍ.
update public.legal_rule set source_kind='official', original_text_loaded=true, enforcement='WARNING',
  source_url='https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf',
  instrument_no='38/2026 (5/1/2026؛ ج.ر. العدد 3 تاريخ 15/1/2026)', article='م.28 بند 6 و7 (إضافة)',
  summary_ar='يضيف بندين إلى المادة 28 من القانون 80/2018: (6) رسوم خدمة جمع النفايات المنزلية الصلبة ونقلها لصالح الإدارات المحلية ضمن نطاقها، من الوحدات السكنية والمؤسسات العامة والخاصة؛ (7) رسوم على بعض المنتجات بحسب كمية أو نوع النفايات الناتجة، تحققها وتحصّلها إدارة الجمارك. نافذ فور نشره في 15/1/2026.',
  conditions_ar='تضع الإدارة المحلية جداول الرسم وتعدّلها سنويًا ضمن حدود دنيا وقصوى شهرية واردة في القانون (انظر صفحة «حدود رسم النفايات»)',
  last_checked_on='2026-11-26' where rule_id='WASTE-38-2026';
update public.legal_rule set summary_ar='تنص المادة 28 على مصادر تمويل الاستراتيجية الوطنية والبرامج المحلية، أولها اعتمادات الموازنة العامة للهيئة الوطنية. أُضيف إليها بالقانون 38/2026 البندان 6 (رسم خدمة الجمع للإدارات المحلية) و7 (رسوم على منتجات تحصّلها الجمارك). تحميل نص المادة الأصلية كاملًا لم يتم بعد؛ البندان المضافان محمّلان في القانون 38/2026.' where rule_id='WASTE-80-28';
insert into public.legal_rule (rule_id, instrument, instrument_no, article, topic, summary_ar, conditions_ar, exceptions_ar, deadline_ar, required_docs_ar, source_url, source_kind, enforcement, review_status, original_text_loaded, last_checked_on, workflow) values
('WASTE-38-6-BANDS','قانون','38/2026','م.28 بند 6-ب','حدود الرسم الشهري لكل نوع مؤسسة','تضع الإدارة المحلية جداول الرسم بحسب نوع المؤسسة ووجهة استعمال المبنى ومساحته وعدد شاغليه، ضمن حدّ أدنى وأقصى شهري لكل فئة (30 فئة) تُحدَّد كنسبة مئوية من الحد الأدنى الرسمي للأجور في القطاع الخاص، مثلًا للمنازل من 1% إلى 4%. الأرقام الكاملة في صفحة «حدود رسم النفايات».','نوع المؤسسة، استعمال المبنى، المساحة، عدد الشاغلين',null,null,'جدول تكليف سنوي','https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf','official','BLOCK','pending_review',true,'2026-11-26','waste'),
('WASTE-38-6-E','قانون','38/2026','م.28 بند 6-د/هـ','قرار البلدية بتفاصيل الرسم وجداول التكليف','على كل إدارة محلية، خلال مهلة أقصاها 3 أشهر من تاريخ صدور القانون، إصدار قرار بتفاصيل الرسوم وطريقة جبايتها ووتيرتها والحوافز على الفرز من المصدر. وتصدر جداول تكليف تُظهر أرقام العقارات وشاغليها ونوع نشاطهم والبدل، وتستوفى بإصدارات سنوية مقسمة على 12 شهرًا مع جداول ملحقة عند أي تغيير.','قرار صادر عن المجلس البلدي',null,'3 أشهر من تاريخ صدور القانون (5/1/2026؛ ونُشر 15/1/2026)','قرار بلدي، جداول تكليف سنوية','https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf','official','WARNING','pending_review',true,'2026-11-26','waste'),
('WASTE-38-6-ZH','قانون','38/2026','م.28 بند 6-ز/ح/ط','التخلف عن الدفع والتحصيل الجبري والدفع الإلكتروني','من تخلف عن الدفع 15 يومًا بعد التبليغ تُفرض عليه الغرامة المنصوص عنها في المادة 109 من قانون الرسوم والعلاوات البلدية رقم 60 تاريخ 12/8/1988. تُطبق إجراءات التحصيل الجبري وأصول الاعتراض في القانون نفسه. يجوز اعتماد الدفع الإلكتروني عبر مؤسسات مالية معتمدة.',null,null,'15 يومًا بعد التبليغ',null,'https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf','official','INFORMATION','pending_review',true,'2026-11-26','waste'),
('WASTE-38-6-GJ','قانون','38/2026','م.28 بند 6-ج/ي','عدم ربط الرسم بشرعية المبنى وعدم الازدواجية','لا يرتبط البدل بشرعية المبنى أو النشاط ولا يضفي استيفاؤه المشروعية على أي إشغال. ويراعى عدم ازدواجية الرسم عند تولي البلديات والاتحادات فرضه وتحصيله.',null,null,null,null,'https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf','official','WARNING','pending_review',true,'2026-11-26','waste'),
('WASTE-38-6-K','قانون','38/2026','م.28 بند 6-و/ك','تعديل القيمة بمرسوم وصلاحية المحافظ والقائمقام','تُعدَّل قيمة الرسم عند الاقتضاء بمرسوم في مجلس الوزراء بناء على اقتراح وزراء البيئة والمالية والداخلية والبلديات. ويتمتع المحافظ والقائمقام، عند قيام كل منهما بدور الإدارة المحلية، بكامل الصلاحيات بما فيها التحقق والتحصيل والمتابعة والتنفيذ، ولهما اعتماد الإدارة المباشرة أو التلزيم.',null,null,null,null,'https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf','official','INFORMATION','pending_review',true,'2026-11-26','waste'),
('WASTE-38-7','قانون','38/2026','م.28 بند 7','الرسوم على المنتجات (الجمارك)','رسوم على بعض المنتجات بحسب كمية أو نوع النفايات الناتجة وفق الجدول رقم 1 المرفق. تتولى إدارة الجمارك تحقق وتحصيل هذه الرسوم؛ وتحدد أصول استعمالها وتخصيصها للإدارة المتكاملة للنفايات بمرسوم؛ ويُعدَّل مقدارها أو تُلغى عن منتجات أو تُفرض على أخرى بمرسوم بناء على اقتراح وزيري البيئة والمالية. لا تحصّلها البلدية.',null,null,null,null,'https://www.lapoleb.com/uploads/media/38-696f454755c0d749571749.pdf','official','INFORMATION','pending_review',true,'2026-11-26','waste')
on conflict (rule_id) do nothing;
